// Binder Town wiki-next — the only script: search, glossary taps, level planner, list filters, the HUD clock, hotbar keys.
(() => {
  const $ = (s, r = document) => r.querySelector(s);
  const $$ = (s, r = document) => [...r.querySelectorAll(s)];
  const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  // the data files carry the same build stamp as this script (Cloudflare caches static files for hours)
  const V = (document.currentScript && new URL(document.currentScript.src).searchParams.get("v")) || "";
  const json = (u) => fetch(V ? `${u}?v=${V}` : u).then((r) => r.json());

  // the HUD clock: the next World Boss (times are Thai time, the game's schedule)
  const clock = $(".clock[data-wb]");
  if (clock) {
    const times = (clock.dataset.wb.match(/\d{1,2}:\d{2}/g) || []).map((t) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; }).sort((a, b) => a - b);
    const tick = () => {
      const now = new Date(), bkk = new Date(now.getTime() + (now.getTimezoneOffset() + 420) * 60000);
      const mins = bkk.getHours() * 60 + bkk.getMinutes();
      const next = times.find((x) => x > mins) ?? times[0] + 1440;
      const left = next - mins, hh = Math.floor(left / 60), mm = left % 60;
      clock.innerHTML = `World Boss ถัดไป <b>${String(Math.floor(next / 60) % 24).padStart(2, "0")}:${String(next % 60).padStart(2, "0")}</b><br><span>อีก ${hh ? `${hh} ชม. ` : ""}${mm} นาที</span>`;
    };
    if (times.length) { tick(); clock.hidden = false; setInterval(tick, 30000); }
  }

  const lit = $("#hotbar .hk.on");
  if (lit && lit.parentElement.scrollWidth > lit.parentElement.clientWidth) lit.parentElement.scrollLeft = lit.offsetLeft - (lit.parentElement.clientWidth - lit.offsetWidth) / 2;

  // keys like the game: 1–0 = the hotbar slots, Esc = back to the first page, / = search
  const typing = () => /INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName || "") || document.activeElement?.isContentEditable;
  document.addEventListener("keydown", (e) => {
    if (e.ctrlKey || e.metaKey || e.altKey || typing() || e.defaultPrevented) return;
    if (document.body.dataset.ownKeys && /^[0-9 ]$/.test(e.key)) return; // the damage calculator uses 1–0 for its moves
    const slot = /^[0-9]$/.test(e.key) && $(`#hotbar a[data-key="${e.key}"]`);
    if (slot) { location.href = slot.getAttribute("href"); return; }
    if (e.key === "Escape" && location.pathname !== "/" && !document.querySelector(".modal.on")) location.href = "/";
  });

  // search: every entry with its picture; substring match on the name (Thai has no spaces), then its sub line
  let idx = null;
  const box = $("[data-results]");
  const fold = (s) => String(s).toLowerCase().normalize("NFKC");
  const show = (q) => {
    if (!box) return;
    if (!q) { box.hidden = true; return; }
    const f = fold(q);
    const hit = idx.filter((e) => fold(e.n).includes(f)).sort((a, b) => fold(a.n).indexOf(f) - fold(b.n).indexOf(f) || a.n.length - b.n.length)
      .concat(idx.filter((e) => !fold(e.n).includes(f) && fold(e.s || "").includes(f))).slice(0, 30);
    box.innerHTML = hit.length ? hit.map((e, i) => `<a href="${e.u}"${i ? "" : ' class="on"'}>${e.i ? `<img class="px" src="${e.i}" alt="">` : '<span class="fall" style="--fc:#5b6876">✦</span>'}<span><b>${esc(e.n)}</b><br><small>${esc(e.s || "")}</small></span><small>${esc(e.k)}</small></a>`).join("") : '<p class="muted" style="padding:8px">ไม่พบ</p>';
    box.hidden = false;
  };
  $$("[data-search]").forEach((inp) => {
    inp.addEventListener("input", async () => { idx ??= await json("/search.json"); show(inp.value.trim()); });
    inp.addEventListener("focus", () => { if (inp.value.trim() && idx) show(inp.value.trim()); });
    inp.addEventListener("keydown", (e) => { if (e.key === "Enter") { const a = box && $("a", box); if (a) location.href = a.getAttribute("href"); } if (e.key === "Escape") { inp.value = ""; show(""); } });
  });
  document.addEventListener("keydown", (e) => { if (e.key === "/" && !typing()) { e.preventDefault(); $("[data-search]")?.focus(); } });
  document.addEventListener("click", (e) => { if (box && !e.target.closest("#hud .search")) box.hidden = true; });

  // glossary: a term opens its explanation right below, tap again to close
  let gloss = null;
  document.addEventListener("click", async (e) => {
    const t = e.target.closest(".term");
    if (!t) return;
    const open = t.nextElementSibling?.classList.contains("tip");
    if (open) { t.nextElementSibling.remove(); t.classList.remove("open"); return; }
    gloss ??= await json("/glossary.json");
    const tip = document.createElement("span");
    tip.className = "tip";
    tip.textContent = gloss[t.dataset.g] || "";
    t.after(tip);
    t.classList.add("open");
  });

  // filters: chips per group + a search box; a row / card shows when it matches every group (values are space-separated
  // words) and its text holds what was typed. A page with a search box but no [data-list] filters every card in main.
  const filters = $("[data-filters]");
  const list = $("[data-list]");
  if (filters && (list || $("[data-find]", filters))) {
    const items = list ? (list.tBodies ? [...list.tBodies[0].rows] : [...list.children]) : $$("main .card");
    const want = {};
    let q = "";
    const apply = () => {
      let n = 0;
      for (const el of items) {
        const ok = Object.entries(want).every(([k, v]) => !v || (el.dataset[k] || "").split(" ").includes(v) || (k === "job" && el.dataset.job === "all"))
          && (!q || fold(el.textContent).includes(q));
        el.hidden = !ok;
        if (ok) n++;
      }
      // a section whose cards are all hidden hides too (maps by region, NPCs by town)
      if (!list) for (const sec of $$("main section.sec")) { const cs = $$(".card", sec); if (cs.length) sec.hidden = cs.every((c) => c.hidden); }
      const c = $("[data-count]", filters);
      if (c) c.textContent = `แสดง ${n.toLocaleString("en-US")} จาก ${items.length.toLocaleString("en-US")}`;
    };
    $$("[data-filter]", filters).forEach((g) => g.addEventListener("click", (e) => {
      const b = e.target.closest("button");
      if (!b) return;
      $$("button", g).forEach((x) => x.classList.toggle("on", x === b));
      want[g.dataset.filter] = b.dataset.v;
      apply();
    }));
    const find = $("[data-find]", filters);
    if (find) find.addEventListener("input", () => { q = fold(find.value.trim()); apply(); });
    apply();
  }

  // level planner: full-EXP maps for your level (the game's rule: level ≤ map top + free gap, band starts ≤ level + 2)
  const pl = $("[data-planner]");
  if (pl) {
    const lv = $("[data-lv]", pl), lvr = $("[data-lvr]", pl), out = $("[data-plout]", pl);
    let plan = null;
    try { const s = Number(localStorage.getItem("wikiLv")); if (s > 0) { lv.value = s; lvr.value = s; } } catch { /* */ }
    const draw = async () => {
      plan ??= await json("/plan.json");
      const L = Math.max(1, Math.min(plan.max, Math.round(Number(lv.value) || 1)));
      try { localStorage.setItem("wikiLv", String(L)); } catch { /* */ }
      // continents: Nacreon maps open from nac.min only; from nac.old the old continent pays nac.mult EXP → Nacreon only
      const nac = plan.nac, open = (m) => !m.nc || !nac || L >= nac.min;
      const pool = plan.maps.filter((m) => open(m) && (!nac || L < nac.old || m.nc));
      const fit = pool.filter((m) => m.b[0] <= L + plan.gap.above && L <= m.b[1] + plan.gap.free).sort((a, b) => b.b[1] - a.b[1]).slice(0, 4);
      const list = fit.length ? fit : pool.filter((m) => m.b[0] <= L).sort((a, b) => b.b[1] - a.b[1]).slice(0, 2);
      const note = nac && L >= nac.old ? `<p class="muted">Lv ${nac.old}+ ฟาร์มทวีปเดิมได้ EXP แค่ ${Math.round(nac.mult * 100)}% — แนะนำเฉพาะแมพทวีป Nacreon</p>` : "";
      out.innerHTML = list.map((m) => `<a class="plmap" href="/map/${m.id}"><span class="rpic">${m.p ? `<img src="${m.p}" alt="">` : ""}</span><span class="ct"><b>${esc(m.n)}${m.nw ? ' <span class="chip warn">ใหม่</span>' : ""}</b><small>Lv ${m.b[0]}–${m.b[1]} · ${esc(m.r)} · EXP เต็มถึง Lv ${m.b[1] + plan.gap.free}</small><span class="mobs">${m.mobs.map((x) => x.i ? `<img src="${x.i}" alt="${esc(x.n)}" title="${esc(x.n)}">` : "").join("")}</span></span></a>`).join("") + note || '<p class="muted">ไม่มีแมพในช่วงนี้</p>';
    };
    lv.addEventListener("input", () => { lvr.value = lv.value; draw(); });
    lvr.addEventListener("input", () => { lv.value = lvr.value; draw(); });
    draw();
  }
})();
